{
  "IP": "neorv32_sysinfo",
  "Conceptual Assets": [
    {
      "Concept ID": "C1",
      "Concept Name": "Writable system-information value",
      "Unit": "neorv32_sysinfo",
      "Information": "A software-visible system-information word initialized to the configured clock frequency and replaceable by a bus write; the module's readback behavior depends on this value.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "no",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Integrity is at risk because bus_req_i.data can overwrite the held system-information value on line 95 when the access condition on line 94 is met, allowing a false value to be reported.",
      "Objectives At Risk": [
        "I"
      ],
      "Attack": "An attacker able to issue a qualifying bus write can replace the reported frequency with a false value at line 95, causing software or an integrator to rely on incorrect system information.",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        95
      ],
      "Held Lines": [
        92,
        95
      ],
      "Exit Lines": [
        168
      ]
    }
  ],
  "Not Kept": [
    {
      "Candidate Name": "Build-time hardware configuration information",
      "Candidate Unit": "neorv32_sysinfo",
      "Merged Into": "",
      "Why Not Kept": "The build-time-values rule bars the generic- and constant-derived memory, cache, boot and peripheral configuration from being conceptual assets because no runtime element changes it, despite its assignments on lines 102-150."
    },
    {
      "Candidate Name": "Bus access command",
      "Candidate Unit": "neorv32_sysinfo",
      "Merged Into": "",
      "Why Not Kept": "The access-command-fields rule treats bus_req_i.stb, bus_req_i.rw and bus_req_i.addr as parts of the access rather than independent information; they only select and qualify the sysinfo access on lines 94 and 161-162."
    },
    {
      "Candidate Name": "Buffered access address",
      "Candidate Unit": "neorv32_sysinfo",
      "Merged Into": "",
      "Why Not Kept": "buf_adr is only a registered copy of the access address used while serving the transfer, so the held-address rule makes it part of the access rather than a separate piece of information on lines 158, 162 and 168."
    },
    {
      "Candidate Name": "Bus response handshake and error status",
      "Candidate Unit": "neorv32_sysinfo",
      "Merged Into": "",
      "Why Not Kept": "The acknowledge only repeats the request strobe and the error is tied to a constant, so bus-handshake-copy and constant-status rules bar them as independent information on lines 160 and 169-170."
    },
    {
      "Candidate Name": "Clock and reset timing",
      "Candidate Unit": "neorv32_sysinfo",
      "Merged Into": "",
      "Why Not Kept": "The clocks-and-resets rule excludes clk_i and rstn_i from conceptual assets under all questions; they only time or reset the logic on lines 58-59 and 89-93."
    }
  ],
  "Notes": []
}
